#!/usr/bin/env python3
"""Render the 4 booktabs LaTeX tables from MECHANISM_RESULTS_DATA.json only."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DATA = json.loads((ROOT / "MECHANISM_RESULTS_DATA.json").read_text())

TIER_TAG = {
    "well_supported": r"\wellsup",
    "statistically_limited_but_reportable": r"\limited",
    "exploratory_not_primary_quantitative_claim": r"\exploratory",
}

PREAMBLE_NOTE = (
    "% Auto-generated by scripts/make_tables.py from MECHANISM_RESULTS_DATA.json.\n"
    "% Every number traces to a frozen, checksum-verified source artifact --\n"
    "% see SOURCE_PROVENANCE.tsv. Do not hand-edit; regenerate instead.\n"
    "% Requires \\usepackage{booktabs} in the host document, and these three\n"
    "% commands defined once in the preamble (support-tier tags used below):\n"
    "%   \\newcommand{\\wellsup}{$\\bullet$}      % >=100 raw QCD\n"
    "%   \\newcommand{\\limited}{$\\circ$}        % 10-99 raw QCD\n"
    "%   \\newcommand{\\exploratory}{$\\times$}   % <10 raw QCD\n"
)


def fmt(x, nd=2):
    return f"{x:.{nd}f}"


# ---------------------------------------------------------------------------
# Table A: Track-B holdout_A E0/E1/E2 operating points
# ---------------------------------------------------------------------------

def table_trackb_mechanism():
    wp = sorted(DATA["track_b"]["working_points"], key=lambda w: (-w["eps_S"], w["arm"]))
    lines = [PREAMBLE_NOTE, r"\begin{table}[htbp]", r"\centering",
              r"\caption{Track-B \texttt{holdout\_A} E0/E1/E2 operating points, fixed "
              r"$\epsilon_S$ (population: \texttt{tight\_exact4}, no mass-plane cut; "
              r"\texttt{holdout\_A} opened once, Phase-4M). "
              r"$R_B$ is seed mean $\pm$ std over 3 seeds; "
              r"raw QCD is the seed-mean raw surviving-QCD count that sets the support tier "
              r"($\bullet\geq100$, $\circ$ 10--99, $\times<$10).}",
              r"\label{tab:trackb_mechanism}",
              r"\begin{tabular}{llrrrc}",
              r"\toprule",
              r"$\epsilon_S$ & Arm & AUC (secondary) & $R_B$ (mean $\pm$ std) & raw QCD (mean) & support \\",
              r"\midrule"]
    prev_eps = None
    for w in wp:
        if prev_eps is not None and w["eps_S"] != prev_eps:
            lines.append(r"\addlinespace")
        prev_eps = w["eps_S"]
        lines.append(
            f"{w['eps_S']:.2f} & {w['arm']} & {fmt(w['auc_mean'], 4)} & "
            f"${fmt(w['R_B_mean'])} \\pm {fmt(w['R_B_std'])}$ & "
            f"{fmt(w['raw_qcd_mean'], 1)} & {TIER_TAG[w['support_tier_of_mean']]} \\\\"
        )
    lines += [r"\bottomrule", r"\end{tabular}", r"\end{table}"]
    (ROOT / "TRACKB_MECHANISM_TABLE.tex").write_text("\n".join(lines) + "\n")
    print("wrote TRACKB_MECHANISM_TABLE.tex")


# ---------------------------------------------------------------------------
# Table B: Track-A eps_S = 0.40 model comparison
# ---------------------------------------------------------------------------

def table_tracka_mechanism():
    models = DATA["track_a"]["fig3_models"]
    lines = [PREAMBLE_NOTE, r"\begin{table}[htbp]", r"\centering",
              r"\caption{Track-A model comparison at $\epsilon_S=0.40$ "
              r"(\texttt{post\_training\_evaluation\_20260815\_v2}, corrected/authoritative). "
              r"Error bars on the two newly-trained models are seed-to-seed std "
              r"(5-fold OOF $\times$ 3 seeds); the 68\% bootstrap CI (primary seed, 2000 "
              r"group-stratified replicates) is given separately. Frozen references have "
              r"no interval computed in any artifact this table draws from.}",
              r"\label{tab:tracka_mechanism}",
              r"\small",
              r"\setlength{\tabcolsep}{4pt}",
              r"\begin{tabular}{lrrl}",
              r"\toprule",
              r"Model & $R_B(\epsilon_S{=}0.40)$ & 68\% bootstrap CI & status \\",
              r"\midrule"]
    status_text = {
        "frozen_reference_single_operating_point": "frozen, single op.\\ pt.",
        "frozen_reference": "frozen ref.\\ (recomp.)",
        "measured_this_benchmark": "measured, this benchmark",
        "frozen_reference_cited_not_recomputed": "frozen ref.\\ (cited)",
    }
    for m in models:
        label = m["label"].replace("\n", " ")
        if m["R_B_err"] is not None:
            val = f"${fmt(m['R_B'])} \\pm {fmt(m['R_B_err'])}$"
            ci = f"[{fmt(m['bootstrap_ci68'][0])}, {fmt(m['bootstrap_ci68'][1])}]"
        else:
            val = f"{fmt(m['R_B'])}"
            ci = "--"
        lines.append(f"{label} & {val} & {ci} & {status_text[m['kind']]} \\\\")
    lines += [r"\bottomrule", r"\end{tabular}", r"\end{table}"]
    (ROOT / "TRACKA_MECHANISM_TABLE.tex").write_text("\n".join(lines) + "\n")
    print("wrote TRACKA_MECHANISM_TABLE.tex")


# ---------------------------------------------------------------------------
# Table C: Track-A supported-rejection boundaries
# ---------------------------------------------------------------------------

def table_support_limits():
    lines = [PREAMBLE_NOTE, r"\begin{table}[htbp]", r"\centering",
              r"\caption{Track-A supported-rejection boundaries, fixed $\epsilon_B$ grid, "
              r"primary seed (20260811) only. Support gate: raw\_background\_rows "
              r"$\geq100$ AND qcd\_raw\_rows $\geq10$ AND qcd\_Neff $\geq10$ (all three "
              r"required). \ding{51} = gate passes; \ding{55} = gate fails -- not reported "
              r"as a supported physical claim anywhere in this package.}",
              r"\label{tab:support_limits}",
              r"\begin{tabular}{llrrrrl}",
              r"\toprule",
              r"Model & $\epsilon_B$ target & $R_B$ & raw bkg. rows & qcd raw rows & qcd $N_{\rm eff}$ & gate \\",
              r"\midrule"]
    name = {"dnn": "Dense DNN", "cmstransformer": "CMS-inspired transformer"}
    for model in ["dnn", "cmstransformer"]:
        for r in DATA["track_a"]["eps_b_tail"][model]:
            gate = r"\ding{51}" if r["scientifically_supportable"] else r"\ding{55}"
            lines.append(
                f"{name[model]} & {r['target_epsilon_B']:g} & {fmt(r['R_B'], 1)} & "
                f"{r['raw_background_rows']} & {r['qcd_raw_rows']} & "
                f"{fmt(r['qcd_Neff'], 2)} & {gate} \\\\"
            )
        lines.append(r"\addlinespace")
    lines += [r"\bottomrule", r"\end{tabular}", "",
               r"\vspace{4pt}", "",
               r"\noindent{\footnotesize \ding{51}/\ding{55} require \texttt{pifont}. "
               r"$\epsilon_B \in \{10^{-3},10^{-4}\}$ fail the gate for both models "
               r"(qcd\_Neff $<$ 10) and must not be quoted as supported rejection numbers.\par}",
               r"\end{table}"]
    (ROOT / "SUPPORT_LIMITS_TABLE.tex").write_text("\n".join(lines) + "\n")
    print("wrote SUPPORT_LIMITS_TABLE.tex")


# ---------------------------------------------------------------------------
# Table D: Track-B mechanism gain E1/E0, E2/E1
# ---------------------------------------------------------------------------

def table_mechanism_gain():
    gain = sorted(DATA["track_b"]["mechanism_gain"], key=lambda r: -r["eps_S"])
    lines = [PREAMBLE_NOTE, r"\begin{table}[htbp]", r"\centering",
              r"\caption{Track-B \texttt{holdout\_A} mechanism gain: seed-paired $R_B$ "
              r"ratios (mean $\pm$ std of the 3 per-seed ratios; support tier = the "
              r"weaker of the two arms entering the ratio at that point).}",
              r"\label{tab:trackb_mechanism_gain}",
              r"\begin{tabular}{lrrcrrc}",
              r"\toprule",
              r" & \multicolumn{3}{c}{$R_B(E1)/R_B(E0)$} & \multicolumn{3}{c}{$R_B(E2)/R_B(E1)$} \\",
              r"\cmidrule(lr){2-4} \cmidrule(lr){5-7}",
              r"$\epsilon_S$ & ratio & \% change & supp. & ratio & \% change & supp. \\",
              r"\midrule"]
    for row in gain:
        a = row["E1_over_E0"]
        b = row["E2_over_E1"]
        lines.append(
            f"{row['eps_S']:.2f} & "
            f"${fmt(a['mean_of_per_seed_ratios'])} \\pm {fmt(a['std_of_per_seed_ratios'])}$ & "
            f"{'+' if a['pct_change_ratio_of_means']>=0 else ''}{fmt(a['pct_change_ratio_of_means'],1)}\\% & "
            f"{TIER_TAG[a['support_tier']]} & "
            f"${fmt(b['mean_of_per_seed_ratios'])} \\pm {fmt(b['std_of_per_seed_ratios'])}$ & "
            f"{'+' if b['pct_change_ratio_of_means']>=0 else ''}{fmt(b['pct_change_ratio_of_means'],1)}\\% & "
            f"{TIER_TAG[b['support_tier']]} \\\\"
        )
    lines += [r"\bottomrule", r"\end{tabular}", "",
               r"\vspace{4pt}", "",
               r"\noindent{\footnotesize Ratio point estimate/std = mean/std of the 3 seed-paired "
               r"ratios $R_B^{(i)}(\mathrm{num})/R_B^{(i)}(\mathrm{den})$; \% change uses "
               r"the ratio of seed means instead (matches the headline prose figures "
               r"in \texttt{HOLDOUT\_A\_ADJUDICATION\_RESULT.md} to within 3\% relative "
               r"outside the exploratory tier -- see VALIDATION\_REPORT.json).\par}",
               r"\end{table}"]
    (ROOT / "TRACKB_MECHANISM_GAIN_TABLE.tex").write_text("\n".join(lines) + "\n")
    print("wrote TRACKB_MECHANISM_GAIN_TABLE.tex")


if __name__ == "__main__":
    table_trackb_mechanism()
    table_tracka_mechanism()
    table_support_limits()
    table_mechanism_gain()
